// =========================================================
// CONFIGURAÇÕES — WORKFLOW DE CORREÇÃO (errata + dados + formadores)
// =========================================================

// MODO_TESTE = true  -> tudo é redirecionado para EMAIL_TESTE
//                       (o assunto mostra quem seria o destinatário real).
// MODO_TESTE = false -> envio real para alunos e formadores.
const MODO_TESTE = true;

// E-mail que recebe as mensagens quando MODO_TESTE = true
const EMAIL_TESTE = 'prof.flavio.spina@gmail.com';

// Planilha (diário QR) do curso CORRETO — alunos e dados vêm daqui
const PLANILHA_ID = '1-rSlEPzgbtv_C7AXVV1SSWi8r12jaULpzwjyllEcj7s';

// Agenda mensal com sala e demais informações do curso
const AGENDA_SHEET_ID = '11_isrdRYiew08xo7rZyBqx1YkvyfR7IRmrHui37x768';

// Aba da agenda a consultar. Vazio ('') = automática, pelo mês da data da
// aula em maiúsculas (ex.: SETEMBRO). Preencha para forçar uma aba específica.
const AGENDA_ABA = 'SETEMBRO';

// Data em que o e-mail errado foi enviado (aparece no texto da errata)
const DATA_ERRO = '09/09/2026';

// Nome do curso ERRADO que apareceu no e-mail enviado por engano
const CURSO_ERRADO = 'Construção colaborativa de Sequências Didáticas de Gênero Textual em interface com o DUA';

// DIAS_A_FRENTE: data da aula mostrada nos e-mails (0 = hoje, 1 = amanhã...)
const DIAS_A_FRENTE = 0;

// Texto exibido no lugar da sala quando nem a agenda nem a aba ID informarem
const AVISO_SALA = 'A sala será orientada no dia do curso, ao chegar ao prédio.';

return [{
  json: {
    MODO_TESTE,
    EMAIL_TESTE,
    PLANILHA_ID,
    AGENDA_SHEET_ID,
    AGENDA_ABA,
    DATA_ERRO,
    CURSO_ERRADO,
    DIAS_A_FRENTE,
    AVISO_SALA
  }
}];

const cfg = $('Config - Variáveis').first().json;
const tz = 'America/Sao_Paulo';

function pad(v) {
  return String(v).padStart(2, '0');
}

const dias = Number(cfg.DIAS_A_FRENTE);
if (!Number.isFinite(dias) || dias < 0) {
  throw new Error('DIAS_A_FRENTE inválido: use um número inteiro >= 0 (0 = hoje).');
}

const now = new Date(new Date().toLocaleString('en-US', { timeZone: tz }));
const target = new Date(now);
target.setDate(target.getDate() + Math.trunc(dias));

const dd = pad(target.getDate());
const mm = pad(target.getMonth() + 1);
const yyyy = target.getFullYear();

const mesNome = target.toLocaleDateString('pt-BR', { timeZone: tz, month: 'long' });

return [{
  json: {
    hoje: `${pad(now.getDate())}/${pad(now.getMonth() + 1)}/${now.getFullYear()}`,
    target_ddmmyyyy: `${dd}/${mm}/${yyyy}`,
    target_ddmm: `${dd}/${mm}`,
    target_dia: dd,
    mes_aba: mesNome.toUpperCase(),
    weekday: target.toLocaleDateString('pt-BR', { timeZone: tz, weekday: 'long' })
  }
}];

// Filtra as linhas da agenda cuja DATA é a data da aula e empacota em UM item.
const prep = $('Preparar Data').first().json;

function pad(v) {
  return String(v).padStart(2, '0');
}

function normalizeDateValue(raw) {
  if (raw === null || raw === undefined || raw === '') return null;

  if (typeof raw === 'number') {
    const excelEpoch = new Date(Date.UTC(1899, 11, 30));
    const date = new Date(excelEpoch.getTime() + raw * 86400000);
    return {
      ddmmyyyy: `${pad(date.getUTCDate())}/${pad(date.getUTCMonth() + 1)}/${date.getUTCFullYear()}`,
      day: pad(date.getUTCDate())
    };
  }

  const str = String(raw).trim();
  if (!str) return null;

  let m = str.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return { ddmmyyyy: `${pad(m[1])}/${pad(m[2])}/${m[3]}`, day: pad(m[1]) };

  m = str.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (m) return { ddmmyyyy: `${m[3]}/${m[2]}/${m[1]}`, day: m[3] };

  m = str.match(/^\d{1,2}$/);
  if (m) return { ddmmyyyy: '', day: pad(str) };

  return null;
}

const agenda = [];

for (const item of items) {
  const row = item.json || {};
  const parsed = normalizeDateValue(row['DATA'] ?? row['Data'] ?? row['data']);
  if (!parsed) continue;

  const bate = (parsed.ddmmyyyy && parsed.ddmmyyyy === prep.target_ddmmyyyy) ||
    (!parsed.ddmmyyyy && parsed.day === prep.target_dia);
  if (!bate) continue;

  agenda.push(row);
}

return [{ json: { _agenda: agenda, _agendaCount: agenda.length } }];

const cfg = $('Config - Variáveis').first().json;
const prep = $('Preparar Data').first().json;
const agenda = ($('Code - Agenda do Dia').first().json._agenda) || [];

const resp = items[0]?.json || {};
if (resp.error) {
  const msg = typeof resp.error === 'string' ? resp.error : (resp.error.message || 'erro desconhecido');
  throw new Error('Falha ao ler a planilha do curso (' + cfg.PLANILHA_ID + '): ' + msg);
}

// resp.valueRanges[0] = ID!D4:F8   | resp.valueRanges[1] = ID!B21:F25
const ranges = Array.isArray(resp.valueRanges) ? resp.valueRanges : [];
const cab = (ranges[0] && ranges[0].values) || [];
const grade = (ranges[1] && ranges[1].values) || [];

const cell = (g, r, c) => String(((g[r] || [])[c] ?? '')).trim();

const nomeCurso = cell(cab, 0, 0);            // D4
const cargaHoraria = cell(cab, 0, 1);         // E4
const modalidade = cell(cab, 0, 2);           // F4
const dataInicio = cell(cab, 2, 0);           // D6
const formadoresNomesRaw = cell(cab, 3, 0);   // D7
const formadoresEmailsRaw = cell(cab, 4, 0);  // D8

if (!nomeCurso) {
  throw new Error('A célula D4 da aba ID está vazia — não foi possível identificar o nome do curso.');
}

function pad(v) {
  return String(v).padStart(2, '0');
}

function toDate(raw) {
  if (raw === null || raw === undefined || raw === '') return null;
  const str = String(raw).trim();
  if (!str) return null;
  let m = str.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return { ddmmyyyy: `${pad(m[1])}/${pad(m[2])}/${m[3]}`, ddmm: `${pad(m[1])}/${pad(m[2])}` };
  m = str.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (m) return { ddmmyyyy: `${m[3]}/${m[2]}/${m[1]}`, ddmm: `${m[3]}/${m[2]}` };
  m = str.match(/^(\d{1,2})\/(\d{1,2})$/);
  if (m) return { ddmmyyyy: '', ddmm: `${pad(m[1])}/${pad(m[2])}` };
  return null;
}

// ----- horário/sala pela grade ID!B21:F25 (linha da data, senão 1ª preenchida) -----
let horarioGrade = '';
let salaGrade = '';
let linhaFallback = null;

for (const r of grade) {
  const temConteudo = String(((r || [])[2] ?? '')).trim() || String(((r || [])[4] ?? '')).trim();
  if (!linhaFallback && temConteudo) linhaFallback = r;

  const d = toDate(r && r[0]);
  if (!d) continue;

  const bate = (d.ddmmyyyy && d.ddmmyyyy === prep.target_ddmmyyyy) ||
    (!d.ddmmyyyy && d.ddmm === prep.target_ddmm);
  if (bate) {
    horarioGrade = String(((r || [])[2] ?? '')).trim();
    salaGrade = String(((r || [])[4] ?? '')).trim();
    linhaFallback = null;
    break;
  }
}

if (!horarioGrade && !salaGrade && linhaFallback) {
  horarioGrade = String(((linhaFallback || [])[2] ?? '')).trim();
  salaGrade = String(((linhaFallback || [])[4] ?? '')).trim();
}

// ----- localizar o curso na agenda mensal (sala e demais informações) -----
function normalize(s = '') {
  return String(s || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function scoreMatch(a, b) {
  if (!a || !b) return 0;
  if (a === b) return 1000;
  if (a.includes(b) || b.includes(a)) return 800;
  const ta = new Set(a.split(' ').filter(Boolean));
  const tb = new Set(b.split(' ').filter(Boolean));
  let common = 0;
  for (const t of ta) if (tb.has(t)) common++;
  if (!common) return 0;
  return common * 10 - Math.abs(ta.size - tb.size);
}

const cursoKey = normalize(nomeCurso);
let agendaRow = null;
let bestScore = 0;

for (const a of agenda) {
  const score = scoreMatch(cursoKey, normalize(a['TÍTULO'] || a['TITULO'] || ''));
  if (score > bestScore) {
    bestScore = score;
    agendaRow = a;
  }
}

const naAgenda = !!agendaRow && bestScore >= 10;
const ag = (campo) => (naAgenda ? String(agendaRow[campo] ?? '').trim() : '');

// Prioridade: agenda mensal > aba ID > aviso/vazio
const salaAgenda = ag('ESPAÇO') || ag('ESPACO') || ag('LOCAL');
const inicioAgenda = ag('INÍCIO') || ag('INICIO');
const terminoAgenda = ag('TÉRMINO') || ag('TERMINO');
const horarioAgenda = inicioAgenda && terminoAgenda
  ? `${inicioAgenda} - ${terminoAgenda}`
  : (inicioAgenda || terminoAgenda);

const sala = salaAgenda || salaGrade || cfg.AVISO_SALA;
const horario = horarioAgenda || horarioGrade;
const etapas = ag('ETAPAS');
const formato = ag('FORMATO');
const gsa = ag('GOOGLE SALA DE AULA');

// ----- formadores: aba ID (D7/D8); se D8 vazio, tenta o campo FORMADORES da agenda -----
function splitNomes(s) {
  return String(s || '')
    .replace(/\r\n?/g, '\n')
    .split(/[,;\n]+/)
    .map(v => v.trim())
    .filter(Boolean);
}

function splitEmails(s) {
  return String(s || '')
    .toLowerCase()
    .split(/[,;\s]+/)
    .map(v => v.trim())
    .filter(Boolean);
}

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

let nomesFormadores = splitNomes(formadoresNomesRaw);
let emailsFormadores = splitEmails(formadoresEmailsRaw).filter(e => emailRegex.test(e));

if (!emailsFormadores.length && naAgenda) {
  // Formato da agenda: "Nome - email" (um por linha)
  const linhas = String(agendaRow['FORMADORES'] ?? agendaRow['PROFESSORES'] ?? '')
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map(v => v.trim())
    .filter(Boolean);

  const nomes = [];
  const emails = [];
  for (const linha of linhas) {
    const m = linha.match(/^(.*?)\s*[-–]\s*([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})$/i) ||
      linha.match(/^()([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})$/i);
    if (m) {
      nomes.push((m[1] || m[2]).trim());
      emails.push(m[2].trim().toLowerCase());
    }
  }
  if (emails.length) {
    nomesFormadores = nomesFormadores.length ? nomesFormadores : nomes;
    emailsFormadores = emails;
  }
}

const professores = [];
const seenProf = new Set();
emailsFormadores.forEach((email, i) => {
  if (seenProf.has(email)) return;
  seenProf.add(email);
  professores.push({
    PROFESSOR_NOME: nomesFormadores[i] || nomesFormadores[0] || email,
    PROFESSOR_EMAIL: email
  });
});

// ----- frases dinâmicas -----
function parseBR(s) {
  const m = String(s || '').match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  return m ? new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1]), 12, 0, 0) : null;
}

function capitalize(s) {
  return s ? s.charAt(0).toUpperCase() + s.slice(1) : s;
}

const alvo = parseBR(prep.target_ddmmyyyy);
const hoje = parseBR(prep.hoje);
const weekday = alvo ? capitalize(alvo.toLocaleDateString('pt-BR', { weekday: 'long' })) : '';
const diff = (alvo && hoje) ? Math.round((alvo - hoje) / 86400000) : null;
const masculino = /sábado|domingo/i.test(weekday);

let fraseAbertura;
let refDia;
if (diff === 0) {
  fraseAbertura = `Hoje, ${weekday},`;
  refDia = `de hoje (${weekday})`;
} else if (diff === 1) {
  fraseAbertura = `Amanhã, ${weekday},`;
  refDia = `de amanhã (${weekday})`;
} else if (diff !== null && diff > 1) {
  fraseAbertura = masculino
    ? `No próximo ${weekday}, dia ${prep.target_ddmmyyyy},`
    : `Na próxima ${weekday}, dia ${prep.target_ddmmyyyy},`;
  refDia = masculino
    ? `do próximo ${weekday} (${prep.target_ddmmyyyy})`
    : `da próxima ${weekday} (${prep.target_ddmmyyyy})`;
} else {
  fraseAbertura = `No dia ${prep.target_ddmmyyyy},`;
  refDia = `do dia ${prep.target_ddmmyyyy}`;
}

return [{
  json: {
    CURSO_CORRETO: nomeCurso,
    CURSO_ERRADO: cfg.CURSO_ERRADO,
    DATA_ERRO: cfg.DATA_ERRO,
    DATA: prep.target_ddmmyyyy,
    DIA_SEMANA: weekday,
    FRASE_ABERTURA: fraseAbertura,
    REF_DIA: refDia,
    HORARIO: horario,
    SALA: sala,
    CARGA_HORARIA: cargaHoraria,
    MODALIDADE: modalidade || formato,
    DATA_INICIO: dataInicio,
    ETAPAS: etapas,
    'GOOGLE SALA DE AULA': gsa,
    FORMADORES: nomesFormadores.join(', ') || emailsFormadores.join(', '),
    PROFESSORES: professores,
    CURSO_NA_AGENDA: naAgenda,
    SCORE_AGENDA: bestScore
  }
}];

// Fila única, na ordem:
//   1) errata para todos os alunos
//   2) dados corretos para todos os alunos
//   3) aviso aos formadores (alunos receberam a confirmação)
const curso = $('Code - Dados do Curso').first().json;

const resp = items[0]?.json || {};
if (resp.error) {
  const msg = typeof resp.error === 'string' ? resp.error : (resp.error.message || 'erro desconhecido');
  throw new Error('Falha ao ler os alunos (FREQUÊNCIA C3:D): ' + msg);
}

const rows = Array.isArray(resp.values) ? resp.values : [];
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const seen = new Set();
const alunos = [];

for (const r of rows) {
  const nome = String((r && r[0]) || '').trim();
  const email = String((r && r[1]) || '').trim().toLowerCase();
  if (!email || !emailRegex.test(email)) continue;
  if (seen.has(email)) continue;
  seen.add(email);
  alunos.push({ NOME: nome || email, EMAIL_ALUNO: email });
}

const professores = Array.isArray(curso.PROFESSORES) ? curso.PROFESSORES : [];

if (!alunos.length && !professores.length) {
  return [{
    json: {
      TIPO_ENVIO: 'NENHUM',
      _motivo: 'Nenhum aluno (FREQUÊNCIA C/D) nem formador (ID D7/D8 ou agenda) com e-mail válido.'
    }
  }];
}

const { PROFESSORES, ...cursoBase } = curso;
const fila = [];

for (const a of alunos) {
  fila.push({ json: { ...cursoBase, ...a, TIPO_ENVIO: 'DESCULPAS' } });
}
for (const a of alunos) {
  fila.push({ json: { ...cursoBase, ...a, TIPO_ENVIO: 'DADOS' } });
}
for (const p of professores) {
  fila.push({ json: { ...cursoBase, ...p, TIPO_ENVIO: 'FORMADOR' } });
}

return fila.map((f, i) => ({ json: { ...f.json, ORDEM: i + 1, TOTAL_FILA: fila.length } }));

