let fila = [];
try {
  fila = $('Code - Montar Fila de Envios').all().map(i => i.json);
} catch (e) {
  fila = [];
}

const desculpas = fila.filter(f => f.TIPO_ENVIO === 'DESCULPAS').length;
const dados = fila.filter(f => f.TIPO_ENVIO === 'DADOS').length;
const formadores = fila.filter(f => f.TIPO_ENVIO === 'FORMADOR').length;

return [{
  json: {
    status: (desculpas + dados + formadores) ? 'CONCLUIDO' : 'SEM_ENVIOS',
    emails_desculpas: desculpas,
    emails_dados_corretos: dados,
    emails_formadores: formadores,
    mensagem: (desculpas + dados + formadores)
      ? 'Correção enviada: erratas, depois dados corretos aos alunos e, por fim, aviso aos formadores.'
      : 'Nenhum destinatário com e-mail válido encontrado.'
  }
}];
